// Where each part answers: its port, from a settings file, fixed, or
// another part's; its address and its Open link; and its settings with the
// ports and addresses of other parts filled in, the backend it needs among
// them.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseEnv } from "node:util";
// The values in a settings (.env) file, or none when it is not there.
export function readSettings(root, file) {
    const path = join(root, file);
    return existsSync(path)
        ? parseEnv(readFileSync(path, "utf8"))
        : {};
}
export function portOf(part, parts, root) {
    const source = part.port;
    if (!source)
        return null;
    if ("fixed" in source)
        return source.fixed;
    if ("part" in source) {
        const other = parts.find((p) => p.id === source.part);
        return other && other !== part ? portOf(other, parts, root) : null;
    }
    const value = Number(readSettings(root, source.env)[source.key]);
    return Number.isInteger(value) && value > 0 ? value : source.default;
}
export function addressOf(part, parts, root) {
    const port = portOf(part, parts, root);
    return port ? `http://127.0.0.1:${String(port)}` : null;
}
// What the Open link points at, if the part has one.
export function linkOf(part, parts, root) {
    if (!part.open)
        return null;
    if (/^https?:/.test(part.open))
        return part.open;
    const address = addressOf(part, parts, root);
    return address ? `${address}${part.open}` : null;
}
// The part's settings with "{port:<part>}" replaced by that part's port,
// and "{address:<part>}" by its address.
export function envOf(part, parts, root) {
    if (!part.env)
        return undefined;
    const other = (id) => parts.find((p) => p.id === id);
    return Object.fromEntries(Object.entries(part.env).map(([key, value]) => [
        key,
        value.replace(/\{(port|address):([\w-]+)\}/g, (_match, what, id) => {
            const found = other(id);
            if (!found)
                return "";
            return what === "port"
                ? String(portOf(found, parts, root) ?? "")
                : (addressOf(found, parts, root) ?? "");
        }),
    ]));
}
// The setting with the address of the backend a part needs: a web app's
// development server sends its /api requests there.
const BACKEND_SETTING = "BACKEND_URL";
// Each part that needs a backend (a part of type backend that answers on a
// port, in its dependsOn) gets that backend's address in BACKEND_URL, so it
// reaches the server it depends on. The core always sets it this way, in
// every factory (decision 0015).
export function withBackendAddress(parts) {
    return parts.map((part) => {
        const backend = part.dependsOn
            .map((id) => parts.find((p) => p.id === id))
            .find((p) => p?.type === "backend" && p.port !== undefined);
        if (!backend)
            return part;
        const address = `{address:${backend.id}}`;
        return { ...part, env: { ...part.env, [BACKEND_SETTING]: address } };
    });
}
